//! Shared `no_std` level manifest schema.
//!
//! Generated by the editor's playtest compiler ([`psxed_project::playtest`])
//! and consumed by the editor-playtest runtime example. The records here
//! describe a level the runtime can resolve through a real residency
//! contract (master asset table, per-room residency lists) -- the
//! current backing store is `include_bytes!`, but the same schema
//! is what future stream-pack / CD-streaming code will resolve
//! against. Runtime-consumed visibility/PVS records live here too
//! because the playtest cooker now emits them and the PSX renderer
//! consumes them directly.
//!
//! # Scope
//!
//! Only the records that are *both written by the editor compiler
//! and consumed by the runtime in this same pass* live here. No
//! speculative future systems (farfield, actors, audio banks) --
//! they land alongside the writer + reader that need them.
//!
//! # `no_std`
//!
//! Built without `alloc`. Records are POD-style with `&'static`
//! borrows: the generated source emits `&'static [u8]` /
//! `&'static [AssetId]` slices that the linker pins next to the
//! `include_bytes!` data. Heap-free by construction.

#![no_std]
#![warn(missing_docs)]

/// Fixed-pool runtime traversal over cooked room portals.
pub mod portal_visibility;

/// Stable identifier assigned to every level asset by the editor
/// compiler. `AssetId` values are deterministic across runs:
/// rooms first (in scene-tree order), then textures (ordered by
/// first use in cooked material slot order).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct AssetId(pub u16);

macro_rules! typed_index {
    ($(#[$meta:meta])* pub struct $name:ident;) => {
        $(#[$meta])*
        #[repr(transparent)]
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        pub struct $name(pub u16);

        impl $name {
            /// Zero index.
            pub const ZERO: Self = Self(0);

            /// Build from raw manifest storage.
            pub const fn new(raw: u16) -> Self {
                Self(raw)
            }

            /// Return raw manifest storage.
            pub const fn raw(self) -> u16 {
                self.0
            }

            /// Convert to `usize` for slice indexing.
            pub const fn to_usize(self) -> usize {
                self.0 as usize
            }
        }
    };
}

typed_index! {
    /// Index into the generated `ROOMS` table.
    pub struct RoomIndex;
}

/// Small fixed-width debug bitset for runtime room/portal telemetry.
///
/// This deliberately stores two 32-bit words instead of a `u64`: it preserves
/// the old 64-bit mask surface for host tooling while keeping PS1 runtime code
/// on native-width integer operations.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct RuntimeDebugMask {
    lo: u32,
    hi: u32,
}

impl RuntimeDebugMask {
    /// Empty mask.
    pub const EMPTY: Self = Self { lo: 0, hi: 0 };

    /// Build from low/high 32-bit words.
    pub const fn from_words(lo: u32, hi: u32) -> Self {
        Self { lo, hi }
    }

    /// Build a mask with `index` set when it fits inside 64 debug bits.
    pub const fn from_index(index: usize) -> Self {
        if index < 32 {
            Self {
                lo: 1u32 << index,
                hi: 0,
            }
        } else if index < 64 {
            Self {
                lo: 0,
                hi: 1u32 << (index - 32),
            }
        } else {
            Self::EMPTY
        }
    }

    /// Build a room-index mask.
    pub const fn from_room(room: RoomIndex) -> Self {
        Self::from_index(room.to_usize())
    }

    /// Low 32 mask bits.
    pub const fn lo(self) -> u32 {
        self.lo
    }

    /// High 32 mask bits.
    pub const fn hi(self) -> u32 {
        self.hi
    }

    /// True when no bits are set.
    pub const fn is_empty(self) -> bool {
        self.lo == 0 && self.hi == 0
    }

    /// Return a copy with `index` set when it fits inside 64 debug bits.
    pub const fn with_index(self, index: usize) -> Self {
        let bit = Self::from_index(index);
        Self {
            lo: self.lo | bit.lo,
            hi: self.hi | bit.hi,
        }
    }

    /// Return a copy with `room` set.
    pub const fn with_room(self, room: RoomIndex) -> Self {
        self.with_index(room.to_usize())
    }

    /// Set `index` when it fits inside 64 debug bits.
    pub fn insert_index(&mut self, index: usize) {
        *self = self.with_index(index);
    }

    /// Set `room`.
    pub fn insert_room(&mut self, room: RoomIndex) {
        *self = self.with_room(room);
    }

    /// Test `index`.
    pub const fn contains_index(self, index: usize) -> bool {
        if index < 32 {
            (self.lo & (1u32 << index)) != 0
        } else if index < 64 {
            (self.hi & (1u32 << (index - 32))) != 0
        } else {
            false
        }
    }
}

impl core::ops::BitOr for RuntimeDebugMask {
    type Output = Self;

    fn bitor(self, rhs: Self) -> Self::Output {
        Self {
            lo: self.lo | rhs.lo,
            hi: self.hi | rhs.hi,
        }
    }
}

impl core::ops::BitOrAssign for RuntimeDebugMask {
    fn bitor_assign(&mut self, rhs: Self) {
        self.lo |= rhs.lo;
        self.hi |= rhs.hi;
    }
}

impl core::ops::BitAnd<u32> for RuntimeDebugMask {
    type Output = u32;

    fn bitand(self, rhs: u32) -> Self::Output {
        self.lo & rhs
    }
}

impl PartialEq<u32> for RuntimeDebugMask {
    fn eq(&self, other: &u32) -> bool {
        self.lo == *other && self.hi == 0
    }
}

