/// One addressable cooked UI scene. Each scene names a contiguous
/// block inside the shared [`UI_NODES`](LevelUiNodeRecord) pool, so
/// the runtime can activate any authored scene as a game state by
/// id without re-cooking. `node_first`/`node_count` index the
/// shared pool; parent indices stored in the pooled nodes are
/// already pool-relative.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelUiScene {
    /// Stable scene id, assigned at author time and preserved across renames.
    pub id: u16,
    /// Display name.
    pub name: &'static str,
    /// First node index into the shared UI node pool.
    pub node_first: u16,
    /// Number of nodes belonging to this scene.
    pub node_count: u16,
    /// How the focused control's highlight ring is drawn and animated.
    pub focus_style: LevelUiFocusStyle,
}

/// Animation applied to the focused control's highlight ring.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LevelUiFocusEffect {
    /// Static outline in `color_a` (the classic ring).
    Solid,
    /// Outline colour breathes between `color_a` (bright) and
    /// `color_b` (dim) on a triangle wave.
    Pulse,
    /// A bright `color_a` head with a gradient tail orbits the
    /// outline perimeter over a faint `color_b` base ring.
    Tracer,
    /// Four corner brackets that breathe outward and pulse between
    /// `color_a` and `color_b` (targeting-reticle look).
    Corners,
}

/// Cooked focus-ring style for one UI scene. All animation is
/// integer-only and driven by the scene clock the renderer already
/// receives, so styles cost a handful of flat quads per frame.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelUiFocusStyle {
    /// Which animation the ring runs.
    pub effect: LevelUiFocusEffect,
    /// Primary colour: solid ring, pulse bright end, tracer head,
    /// bracket bright end.
    pub color_a: (u8, u8, u8),
    /// Secondary colour: pulse dim end, tracer tail/base ring,
    /// bracket dim end. Unused by `Solid`.
    pub color_b: (u8, u8, u8),
    /// Full animation cycle in vblank-paced UI frames. `0` freezes
    /// the animation at its brightest phase.
    pub period: u16,
    /// Ring/bracket line thickness in pixels, clamped to `1..=4`.
    pub thickness: u8,
    /// Gap between the control's rect and the ring, in pixels.
    pub margin: u8,
    /// Corner bracket arm length in pixels (`Corners` only).
    pub corner_len: u8,
}

impl LevelUiFocusStyle {
    /// The pre-style focus ring: static 1px yellow outline, 1px out.
    /// Scenes cooked without an authored style keep this exact look.
    pub const DEFAULT: Self = Self {
        effect: LevelUiFocusEffect::Solid,
        color_a: (248, 224, 96),
        color_b: (96, 88, 40),
        period: 96,
        thickness: 1,
        margin: 1,
        corner_len: 8,
    };
}

/// Runtime world layer attached to a composed scene state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LevelWorldLayer {
    /// No 3D/gameplay world is rendered or updated.
    None,
    /// Run the project gameplay/level scene.
    Gameplay,
}

/// Sentinel meaning "this scene state has no UI overlay".
pub const UI_SCENE_NONE: u16 = u16::MAX;

/// Runtime flags for [`LevelSceneState`].
pub mod scene_state_flags {
    /// Route menu/navigation input to the state's UI scene.
    pub const UI_INPUT: u16 = 1 << 0;
    /// Keep the gameplay/world layer frozen while this state is active.
    pub const PAUSE_WORLD: u16 = 1 << 1;
}

/// One composed runtime scene. A state may be 2D-only, 3D-only, or a
/// 3D world with a 2D overlay. Flow entries point at these records so
/// loading/unloading policy can become state-driven instead of being
/// implicit in "menu versus gameplay".
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelSceneState {
    /// Stable cooked state id.
    pub id: u16,
    /// Display/debug name.
    pub name: &'static str,
    /// World layer to update/render.
    pub world: LevelWorldLayer,
    /// Optional [`LevelUiScene::id`] drawn over the world.
    pub ui_scene: u16,
    /// Runtime flags from [`scene_state_flags`].
    pub flags: u16,
}

/// One state in the game flow graph. `SceneState` is the modern
/// composable form. `UiScene` and `Gameplay` remain compatibility
/// aliases for older generated manifests and gameplay-only examples.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FlowState {
    /// Enter the composed [`LevelSceneState`] with this id.
    SceneState {
        /// Target [`LevelSceneState::id`].
        state: u16,
    },
    /// Show a UI scene by its [`LevelUiScene::id`].
    UiScene {
        /// Target scene id.
        scene: u16,
    },
    /// Run the gameplay/level simulation.
    Gameplay,
}

/// Cooked game-state flow definition. `states` is the addressable
/// state table and `entry` is the index into `states` the runtime
/// begins in. Plain `Copy` data so it lives in a generated `static`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GameFlow {
    /// Flow state table.
    pub states: &'static [FlowState],
    /// Addressable composed scene-state table.
    pub scene_states: &'static [LevelSceneState],
    /// Index into `states` of the starting state.
    pub entry: u16,
}

/// Full-screen transition effect kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LevelTransitionKind {
    /// No transition; switch states immediately.
    None,
    /// Darken the current frame toward `color`.
    Fade,
    /// Cover the frame with deterministic random blocks.
    BlockDissolve,
    /// Horizon-Glide-style digital break: tears, static blocks, then blackout.
    GlitchBreak,
}

/// Cooked full-screen transition settings.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelTransition {
    /// Effect variant.
    pub kind: LevelTransitionKind,
    /// Duration in visual frames. `0` behaves like [`LevelTransitionKind::None`].
    pub frames: u16,
    /// Overlay colour. Usually black.
    pub color: [u8; 3],
    /// Deterministic noise seed for block/glitch effects.
    pub seed: u16,
}

impl LevelTransition {
    /// No transition.
    pub const NONE: Self = Self {
        kind: LevelTransitionKind::None,
        frames: 0,
        color: [0, 0, 0],
        seed: 0,
    };

    /// Default glitch transition tuned for menu/title handoffs.
    pub const GLITCH_BREAK: Self = Self {
        kind: LevelTransitionKind::GlitchBreak,
        frames: 45,
        color: [0, 0, 0],
        seed: 0x4b1d,
    };

    /// Whether this transition should delay a state switch.
    pub const fn is_active(self) -> bool {
        !matches!(self.kind, LevelTransitionKind::None) && self.frames != 0
    }
}

/// Screen-space UI node kind.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LevelUiNodeKind {
    /// Fixed-resolution root canvas.
    Canvas,
    /// Organizational group.
    Group,
    /// Solid rectangle.
    Rect,
    /// Text label.
    Label,
    /// Textured screen-space image.
    Image,
    /// Horizontal value bar.
    Bar,
    /// Interactive button: a filled rect with a centered label that
    /// fires a [`LevelUiAction`] when activated. Activation handling
    /// is a later step; cooking and rendering land now.
    Button,
    /// Interactive slider bound to a project option: a track, a
    /// proportional fill, and a draggable knob. The bound option id
    /// lives in [`LevelUiNodeRecord::option`]. Value changes are a
    /// later step.
    Slider,
    /// Non-visual CD-DA music cue for the containing UI scene. The
    /// cooked track number lives in [`LevelUiNodeRecord::option`],
    /// volume percentage in [`LevelUiNodeRecord::value`], and loop state
    /// in [`ui_node_flags::MUSIC_LOOP`].
    Music,
    /// Non-visual auto-advance timer: fires its [`LevelUiAction`] once
    /// per scene entry after the cooked delay. The delay in vblank
    /// ticks lives in [`LevelUiNodeRecord::value`] as a
    /// `ConstantQ12`; [`ui_node_flags::TIMER_SKIPPABLE`] lets a CROSS
    /// press fire it early when the scene has no focusable control
    /// (the splash-screen idiom).
    Timer,
}

/// Runtime value source for data-bound UI elements.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LevelUiValueBinding {
    /// Literal Q12 fixed-point value.
    ConstantQ12(i32),
    /// Live project option value.
    Option(u16),
    /// Player health value.
    PlayerHealth,
    /// Player health maximum.
    PlayerHealthMax,
    /// Player stamina value.
    PlayerStamina,
    /// Player stamina maximum.
    PlayerStaminaMax,
    /// Live load progress while the engine streams the next state's
    /// world, in Q12 (0..=4096). Resolves to 0 outside a loading
    /// screen. Bind a Bar's value to this (max `ConstantQ12(4096)`)
    /// to get a real filling load bar.
    LoadingProgress,
}

/// UI event that can fire one of a node's cooked SFX cues.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LevelUiSfxEvent {
    /// Focus moved onto this control.
    Focus,
    /// Button activation / confirm.
    Activate,
    /// Slider value changed by one authored step.
    SliderNudge,
    /// Slider was nudged while already clamped at its min/max.
    SliderLimit,
}

/// One cooked UI SFX sample blob. Samples are global to a cooked level and
/// nodes reference them indirectly through [`LevelUiSfxCueRecord::sample`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelUiSfxSampleRecord {
    /// Cooked `.psau` bytes, usually from `include_bytes!`.
    pub bytes: &'static [u8],
}

/// One authored SFX cue for a UI node event.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelUiSfxCueRecord {
    /// Index into the generated `UI_SFX_SAMPLES` table.
    pub sample: u16,
    /// Event that triggers this cue.
    pub event: LevelUiSfxEvent,
    /// Per-play volume as a percentage of full voice volume.
    pub volume_percent: u8,
    /// Pitch multiplier in Q12 (`4096` = source pitch).
    pub pitch_q12: u16,
    /// Reserved runtime flags.
    pub flags: u16,
}

/// Action a [`LevelUiNodeKind::Button`] fires when activated. Plain
/// `Copy` data carrying compact ids so it lives in a generated
/// `static`. Activation/navigation is wired in a later step.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LevelUiAction {
    /// Switch the game flow to the composed scene state by id.
    GotoState {
        /// Target [`LevelSceneState::id`].
        state: u16,
    },
    /// Switch to a composed scene state with a full-screen transition.
    TransitionToState {
        /// Target [`LevelSceneState::id`].
        state: u16,
        /// Transition to play before revealing the target.
        transition: LevelTransition,
    },
    /// Switch the game flow to the named [`LevelUiScene`] by id.
    GotoScene {
        /// Target [`LevelUiScene::id`].
        scene: u16,
    },
    /// Switch to a UI scene with a full-screen transition.
    TransitionToScene {
        /// Target [`LevelUiScene::id`].
        scene: u16,
        /// Transition to play before revealing the target.
        transition: LevelTransition,
    },
    /// Enter the gameplay/level simulation.
    StartGameplay,
    /// Enter gameplay with a full-screen transition.
    StartGameplayTransition {
        /// Transition to play before revealing gameplay/loading.
        transition: LevelTransition,
    },
    /// Return to the previous menu/scene.
    Back,
    /// Adjust a project option by a signed delta.
    SetOption {
        /// Target option id (mirrors the authored `OptionId`).
        option: u16,
        /// Signed step applied to the option value.
        delta: i32,
    },
    /// Game-specific action dispatched by opaque id.
    Game {
        /// Caller-defined action id.
        id: u16,
    },
}

/// Sentinel meaning "this node binds to no project option". Sprite-strip
