/// One cooked project option: a runtime-tunable integer with a bounded
/// range, step, and default. Sliders ([`LevelUiNodeRecord::option`]) and
/// `SetOption` button actions ([`LevelUiAction::SetOption`]) reference an
/// option by [`Self::id`]. The authoring side's richer kinds (int range,
/// enum, bool) all flatten to this integer triple at cook time: an enum is
/// `[0, variants - 1]` step `1`, a bool is `[0, 1]` step `1`.
///
/// Plain `Copy` POD so a generated `OPTIONS` static lives in the linker's
/// rodata next to the rest of the manifest.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelOptionDef {
    /// Stable option id (mirrors the authored `OptionId`, low 16 bits).
    /// Matched against [`LevelUiNodeRecord::option`] and
    /// [`LevelUiAction::SetOption::option`].
    pub id: u16,
    /// Inclusive minimum value.
    pub min: i32,
    /// Inclusive maximum value.
    pub max: i32,
    /// Step applied per slider nudge (the `SetOption` delta is used as-is).
    pub step: i32,
    /// Initial value the runtime store seeds with.
    pub default: i32,
}

/// One cooked screen-space UI node.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelUiNodeRecord {
    /// Parent UI node index, or `None` for the root canvas.
    pub parent: Option<UiNodeIndex>,
    /// Node kind.
    pub kind: LevelUiNodeKind,
    /// Left edge in canvas pixels.
    pub x: i16,
    /// Top edge in canvas pixels.
    pub y: i16,
    /// Width in canvas pixels.
    pub width: u16,
    /// Height in canvas pixels.
    pub height: u16,
    /// Primary colour: fill for `Rect`/`Bar`/`Button`, text tint for
    /// `Label`, track colour for `Slider`.
    pub color: [u8; 3],
    /// Secondary colour: `Bar` background or `Slider` fill.
    pub background: [u8; 3],
    /// Tertiary colour, currently the `Slider` knob.
    pub accent: [u8; 3],
    /// Optional paint index overriding [`Self::color`], or [`UI_PAINT_NONE`].
    pub color_paint: u16,
    /// Optional paint index overriding [`Self::background`], or [`UI_PAINT_NONE`].
    pub background_paint: u16,
    /// Optional paint index overriding [`Self::accent`], or [`UI_PAINT_NONE`].
    pub accent_paint: u16,
    /// Current value binding for `Bar`.
    pub value: LevelUiValueBinding,
    /// Maximum value binding for `Bar`.
    pub max: LevelUiValueBinding,
    /// Texture asset for `Image` or a sprite-strip `Bar`, or
    /// `AssetId(u16::MAX)`.
    pub texture_asset: AssetId,
    /// Animated vertex-colour preset for `Image`.
    pub image_effect: LevelUiImageEffect,
    /// Text for `Label`/`Button`.
    pub text: &'static str,
    /// Runtime lookup tag for dynamic labels. Empty means untagged.
    pub tag: &'static str,
    /// Action fired by a `Button`. Ignored by other kinds.
    pub action: LevelUiAction,
    /// Project option a `Slider` binds to; sprite-strip frame count for a
    /// textured `Bar`; otherwise [`UI_OPTION_NONE`].
    pub option: u16,
    /// Clockwise visual rotation around this node's centre, in degrees.
    pub rotation_degrees: i16,
    /// Runtime flags.
    pub flags: u16,
    /// First index into the generated `UI_SFX_CUES` table, or
    /// [`UI_SFX_NONE`] when this node has no SFX.
    pub sfx_first: u16,
    /// Number of SFX cues belonging to this node.
    pub sfx_count: u8,
    /// Font selector for `Label` / `Button` text: an index into the font
    /// table the caller passes to the UI renderer. `0` is the default font;
    /// an index past the end of the table falls back to font `0`. Lets a
    /// scene mix, e.g., a large title font and a small body font. Ignored by
    /// non-text node kinds.
    pub font: u8,
    /// Q8 scale for `Label` / `Button` text (`256` = 1.0x). Runtime renderers
    /// clamp this to their supported range and ignore it for non-text node
    /// kinds.
    pub font_scale: u16,
    /// Extra signed screen pixels inserted between adjacent glyphs. Runtime
    /// renderers ignore it for non-text node kinds.
    pub letter_spacing: i8,
}

/// Direction a focus move travels across a menu's focusable rects.
///
/// Maps one-to-one to the four d-pad directions at the runtime call
/// site and to the arrow keys in the editor's nav preview. Both
/// callers drive the same [`next_focus`] resolver through this enum so
/// editor and runtime agree on which control a press lands on.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NavDir {
    /// Toward smaller screen Y.
    Up,
    /// Toward larger screen Y.
    Down,
    /// Toward smaller screen X.
    Left,
    /// Toward larger screen X.
    Right,
}

/// One focusable control's absolute on-screen rectangle, in canvas
/// pixels. The caller builds these from its own node model (cooked
/// [`LevelUiNodeRecord`]s at runtime, authored `UiNode`s in the
/// editor), so the resolver stays input- and model-agnostic: it is
/// pure geometry plus integer math.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct NavRect {
    /// Left edge in canvas pixels.
    pub x: i16,
    /// Top edge in canvas pixels.
    pub y: i16,
    /// Width in canvas pixels.
    pub w: u16,
    /// Height in canvas pixels.
    pub h: u16,
}

impl NavRect {
    /// Center X doubled, so the half-pixel center stays exact in
    /// integer math (a 3-wide rect centers at x + 1.5). Comparisons
    /// and gaps below all work in this doubled space.
    #[inline]
    const fn center_x2(self) -> i32 {
        self.x as i32 * 2 + self.w as i32
    }

    /// Center Y doubled. See [`NavRect::center_x2`].
    #[inline]
    const fn center_y2(self) -> i32 {
        self.y as i32 * 2 + self.h as i32
    }
}

/// Pick the focusable rect to move to from `current` in direction
/// `dir`, or `None` if nothing lies that way.
///
/// # Rule
///
/// Working in doubled-center space (so centers are exact integers):
/// a candidate is eligible only if its center is strictly past the
/// current center along the primary axis of `dir` (above for `Up`,
/// right for `Right`, and so on). Among eligible candidates the score
/// is `primary_gap + secondary_penalty`, where `primary_gap` is the
/// forward distance along the move axis and `secondary_penalty` is the
/// perpendicular offset. The penalty is weighted heavier than the gap
/// so the move prefers the control most in line with the press before
/// reaching for one far off to the side; ties break toward the lower
/// index for determinism. All integer, no allocation, `no_std`.
///
/// `current` out of range, or a candidate list where nothing is
/// eligible, both yield `None`.
pub fn next_focus(rects: &[NavRect], current: usize, dir: NavDir) -> Option<usize> {
    let from = rects.get(current).copied()?;
    let from_cx = from.center_x2();
    let from_cy = from.center_y2();

    // Perpendicular offset is weighted so a control directly in line
    // with the press always wins over one the same forward distance
    // away but off to the side. 2x keeps it integer and is enough to
    // dominate the typical primary gap without overflowing i32 for any
    // sane canvas size.
    const SECONDARY_WEIGHT: i32 = 2;

    let mut best: Option<(usize, i32)> = None;
    for (index, candidate) in rects.iter().enumerate() {
        if index == current {
            continue;
        }
        let cx = candidate.center_x2();
        let cy = candidate.center_y2();
        let (primary_gap, secondary) = match dir {
            NavDir::Up => (from_cy - cy, (cx - from_cx).abs()),
            NavDir::Down => (cy - from_cy, (cx - from_cx).abs()),
            NavDir::Left => (from_cx - cx, (cy - from_cy).abs()),
            NavDir::Right => (cx - from_cx, (cy - from_cy).abs()),
        };
        // Must make real forward progress along the move axis.
        if primary_gap <= 0 {
            continue;
        }
        let score = primary_gap + secondary * SECONDARY_WEIGHT;
        match best {
            Some((_, best_score)) if best_score <= score => {}
            _ => best = Some((index, score)),
        }
    }
    best.map(|(index, _)| index)
}

/// Pick the initial focus: the top-left-most focusable rect.
///
/// Smaller screen Y wins first (top), then smaller screen X (left),
/// then the lower index. `None` for an empty list. Deterministic
/// integer compares so editor and runtime agree on the default focus.
pub fn first_focus(rects: &[NavRect]) -> Option<usize> {
    let mut best: Option<(usize, i32, i32)> = None;
    for (index, rect) in rects.iter().enumerate() {
        let cy = rect.center_y2();
        let cx = rect.center_x2();
        let better = match best {
            None => true,
            Some((_, best_cy, best_cx)) => cy < best_cy || (cy == best_cy && cx < best_cx),
        };
        if better {
            best = Some((index, cy, cx));
        }
    }
    best.map(|(index, _, _)| index)
}

/// Hard cap per Character resource. Combat stays bounded on PS1: the runtime
/// scans this tiny slice only during an active attack and rejects room/radius/
/// AABB misses before sampling an opposing pose.
pub const MAX_CHARACTER_COMBAT_CAPSULES: usize = 16;

/// Flags for [`CombatCapsuleRecord::flags`].
pub mod combat_capsule_flags {
    /// Volume receives damage.
    pub const HURTBOX: u8 = 1 << 0;
    /// Volume deals damage during its action/frame window.
    pub const HITBOX: u8 = 1 << 1;
}

/// Compact rig-attached combat capsule. Endpoints are signed 16-bit because
/// they remain in one joint's local model space; the cook rejects values that
/// do not fit instead of charging the runtime for six 32-bit coordinates.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CombatCapsuleRecord {
    /// Cooked skeleton joint index.
    pub joint: u8,
    /// See [`combat_capsule_flags`].
    pub flags: u8,
    /// Action slot that activates a hitbox. Ignored for hurtboxes.
    pub action: u8,
    /// Reserved/alignment byte.
    pub reserved: u8,
    /// Joint-local segment start.
    pub start: [i16; 3],
    /// Joint-local segment end.
    pub end: [i16; 3],
    /// Capsule radius in engine units.
    pub radius: u16,
    /// First active animation frame, inclusive. Ignored for hurtboxes.
    pub active_start_frame: u16,
    /// Last active animation frame, inclusive. Ignored for hurtboxes.
    pub active_end_frame: u16,
    /// Health damage dealt by a hitbox.
    pub damage: u16,
    /// Poise damage dealt by a hitbox.
    pub poise_damage: u16,
}

/// Cooked weapon-local hit shape.
///
/// Authoring-only today: no runtime path reads the geometry (the old
/// render-side evaluator was counter-only and was removed). The live
/// hit volumes are the melee arc and rig-attached
/// [`CombatCapsuleRecord`]s; a weapon's [`WeaponHitboxRecord`]
/// contributes only its active frame window to the melee spec.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WeaponHitShapeRecord {
    /// Box hit volume local to the weapon grip.
    Box {
        /// Local center.
        center: [i32; 3],
        /// Half extents.
        half_extents: [u16; 3],
    },
    /// Capsule hit volume local to the weapon grip.
    Capsule {
        /// Local start.
        start: [i32; 3],
        /// Local end.
        end: [i32; 3],
        /// Radius.
        radius: u16,
    },
}

/// One weapon hitbox and its active animation-frame window. The
/// window bounds the player melee arc's hit frames
/// (`player_melee_spec`); the shape is authoring-only data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WeaponHitboxRecord {
    /// Display name.
    pub name: &'static str,
    /// Local shape.
    pub shape: WeaponHitShapeRecord,
    /// First active frame.
    pub active_start_frame: u16,
    /// Last active frame.
    pub active_end_frame: u16,
    /// Reserved.
    pub flags: u16,
}

/// Cooked weapon resource: optional visual model plus grip and
/// hitbox slice. The visual model is optional so designers can
/// author combat volumes before art exists.
///
/// The `arc_*`/`damage` fields are the phase-3 melee-combat contract
/// (docs/game-runtime-plan.md): update-band hit resolution sweeps a
/// flat XZ ARC in front of the wielder -- `arc_reach` engine units
/// long, `arc_half_angle` PSX angle units wide to each side of the
/// facing -- against enemy hurtbox cylinders. The grip-local hitbox
/// SHAPES stay a render/debug aid; the arc is the authoritative
/// gameplay volume (capsule/point vs arc is the phase-3 shape, no
/// per-bone hitboxes). The hitboxes' `active_start_frame`/
/// `active_end_frame` windows double as the attack's ACTIVE window in
/// character attack-clip animation frames: frames before the earliest
/// window are the windup, frames after the latest are the recovery.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LevelWeaponRecord {
    /// Display name.
    pub name: &'static str,
    /// Optional visual model.
    pub model: Option<ModelIndex>,
    /// Character socket this weapon expects by default.
    pub default_character_socket: &'static str,
    /// Weapon-local grip/pivot name.
    pub grip_name: &'static str,
    /// Weapon-local grip translation.
    pub grip_translation: [i32; 3],
    /// Weapon-local grip rotation, Q12 turns.
    pub grip_rotation_q12: [i16; 3],
    /// First hitbox in `WEAPON_HITBOXES`.
    pub hitbox_first: WeaponHitboxIndex,
    /// Number of hitboxes.
    pub hitbox_count: u16,
    /// Melee arc reach from the wielder's origin, engine units.
    /// The cook rejects 0 (a reachless weapon can never connect).
    pub arc_reach: u16,
    /// Melee arc half-width to each side of the facing, PSX angle
    /// units (4096 = full turn; cooked from authored degrees).
    pub arc_half_angle: u16,
    /// Damage one light-attack connection applies. The cook rejects 0.
    pub damage: u16,
    /// Poise damage one light-attack connection applies (0 = this
    /// weapon never staggers).
    pub poise_damage: u16,
    /// Reserved.
    pub flags: u16,
}

/// One Equipment component cooked from an Entity.
